      options: ["¬w¬xȳ¬z + w¬xȳ¬z + ¬w¬xy¬z + w¬xy¬z + xz","¬w¬xȳ¬z + ¬w¬xy¬z + w¬xyz + xz","¬w¬xȳ¬z + w¬xȳ¬z + w¬xȳz + xz","¬x¬z + xz"],
